Schema::create('users', function (Blueprint $table) {
            $table->id();
            // PK segue `id` int; `uuid` é a route key (trait TemUuid) — id
            // numérico na URL devolve 404 e ninguém enumera por sequência.
            $table->uuid('uuid')->unique();
            $table->string('name');
            $table->string('email')->unique();
            $table->timestamp('email_verified_at')->nullable();
            $table->string('password');
            $table->string('avatar_url')->nullable();
            $table->rememberToken();
            $table->timestamps();
        });

Schema::table('users', function (Blueprint $table): void {
            // ponytail: sem índice de propósito — boolean é de baixa cardinalidade, e o filtro de
            // pendentes roda sobre a tabela de usuários de UMA organização.
            $table->boolean('aprovacao_pendente')->default(false)->after('email_verified_at');
        });

Schema::table('users', function (Blueprint $table): void {
            // `default('interno')`: todo caminho que NÃO diz de onde veio é interno — admin
            // criando pela tela, seeder, `kit:admin`. Só convite, registro e provedor marcam.
            $table->string('origem', 32)->default('interno')->after('email_verified_at');
        });

Schema::create($tableNames['roles'], static function (Blueprint $table) use ($teams, $columnNames) {
            $table->id(); // role id
            if ($teams || config('permission.testing')) { // permission.testing is a fix for sqlite testing
                $table->unsignedBigInteger($columnNames['team_foreign_key'])->nullable();
                $table->index($columnNames['team_foreign_key'], 'roles_team_foreign_key_index');
            }
            $table->string('name');
            $table->string('guard_name');
            $table->timestamps();
            if ($teams || config('permission.testing')) {
                $table->unique([$columnNames['team_foreign_key'], 'name', 'guard_name']);
            } else {
                $table->unique(['name', 'guard_name']);
            }
        });

Schema::create('tenants', function (Blueprint $table): void {
            $table->id();
            $table->uuid('uuid')->unique();
            $table->string('nome');
            // Segmento da URL em /app/{slug} — é o `slugAttribute` do painel.
            $table->string('slug')->unique();
            // Exclusão é lógica: desligar um tenant é dado, não DELETE.
            $table->boolean('ativo')->default(true);
            $table->timestamps();
        });

Schema::table('tenants', function (Blueprint $table): void {
            // 7 caracteres: `#RRGGBB`. O ColorPicker do Filament grava neste formato com `->hex()`.
            $table->string('cor_primaria', 7)->nullable()->after('ativo');

            // Path relativo no disk `public`, no mesmo formato de `users.avatar_url`.
            $table->string('logo')->nullable()->after('cor_primaria');
        });

Schema::create('convites', function (Blueprint $table): void {
            $table->id();
            $table->uuid('uuid')->unique();

            $table->string('email')->index();

            // sha256 em hex: 64 chars, determinístico, indexável — é o que torna a busca
            // POR TOKEN um lookup de índice único. Nullable porque quem grava é
            // `Convite::enviar()`, depois do `create()` da tela.
            $table->string('token', 64)->nullable()->unique();

            // Sem cascadeOnDelete: apagar o papel de um convite pendente tem de doer na
            // hora, em vez de deixar o convite aceitar com papel nulo.
            $table->foreignId('role_id')
                ->constrained(config('permission.table_names.roles', 'roles'));

            // Só preenchida com a tenancy ligada. A tabela `tenants` existe nos dois modos.
            $table->foreignId('tenant_id')->nullable()->constrained();

            // Quem convidou. nullOnDelete: apagar o admin não apaga o histórico do convite.
            $table->foreignId('convidado_por_id')->nullable()
                ->constrained('users')->nullOnDelete();

            // Nullable porque só `enviar()` sabe o prazo: a linha nasce no `create()` do
            // Filament e ganha token e validade no `afterCreate()`. NULL falha fechado —
            // `expira_em > now()` não casa com NULL, então convite sem envio não vale.
            $table->timestamp('expira_em')->nullable();
            $table->timestamp('aceito_em')->nullable();

            $table->timestamps();
        });

Schema::table('convites', function (Blueprint $table): void {
            /*
             * O SEGUNDO token do convite, hasheado como o primeiro. Um lembrete gera um
             * token novo e grava o hash aqui, SEM tocar em `token`: o link original
             * continua valendo, então nada é revogado nem se o lembrete cair no spam.
             * Cada lembrete sobrescreve esta coluna — no máximo dois links vivos por
             * convite, os dois morrendo com o mesmo `expira_em`. Ver ADR-01.
             */
            $table->string('token_lembrete', 64)->nullable()->unique();

            /*
             * Quando o convite foi enviado de verdade — e NÃO `created_at`: `enviar()` é
             * também o reenvio, então `created_at` pode estar a semanas do último envio.
             * Nulo em toda linha anterior a esta migration, o que as mantém fora dos
             * lembretes: `enviado_em <= ?` nunca casa com NULL. Ver ADR-02.
             */
            $table->timestamp('enviado_em')->nullable();

            // Quantos lembretes já saíram para o envio corrente. Zerado por `enviar()`.
            $table->unsignedTinyInteger('lembretes_enviados')->default(0);
        });

Schema::create('projetos', function (Blueprint $table): void {
            $table->id();
            $table->uuid('uuid')->unique();
            $table->foreignId('tenant_id')->constrained()->cascadeOnDelete();
            $table->string('nome');
            $table->timestamps();

            // Toda listagem filtra por tenant primeiro: o índice acompanha o
            // formato real da query, não a ordem em que as colunas nasceram.
            $table->index(['tenant_id', 'nome']);
        });
